/** One list, rendered with its nested lists inside their parent item. */
function renderList(items, definitions) {
  const rendered = items.map(item => {
    const text = renderInline(item.text, definitions)
    if (item.children.length === 0) {
      return `<li>${text}</li>`
    }
    return `<li>${text}\n${renderList(item.children, definitions)}\n</li>`
  })
  return `<ul>\n${rendered.join('\n')}\n</ul>`
}

